set-variable.value:
@{
      if (context.Request.Body == null) { return ""; }
      var body = JToken.Parse(context.Request.Body.As<string>(preserveContent: true));
      if (body.Type != JTokenType.Object) { return ""; }
      var text = body["text"];
      if (text == null || text.Type != JTokenType.String) { return ""; }
      return (string)text;
    }

send-request.set-body:
@{
            return new JObject(
              new JProperty("model", "{{decision1-deployment}}"),
              new JProperty("state", new JObject(new JProperty("text", (string)context.Variables["requestText"]))),
              new JProperty("questions", new JObject(
                new JProperty("has_pii", new JObject(
                  new JProperty("type", "choice"),
                  new JProperty("instructions", "state.textの内容を対象に、個人を特定できる情報（PII）が含まれているか分類してください。住所であっても公知の情報（例: 国会議事堂の住所）や明らかなダミー値、マスクされた値は個人情報として扱いません。また、個人情報の種類に一般的に言及しているだけの場合は、PIIとはみなしません。"),
                  new JProperty("criteria", new JObject(
                    new JProperty("pii", "具体的な個人の氏名、個人のメールアドレス、電話番号、自宅の住所、クレジットカード番号、または日本の個人番号（マイナンバー）の値を含む。"),
                    new JProperty("no_pii", "上記の個人情報の具体的な値をいずれも含まない。")
                  ))
                ))
              ))
            ).ToString();
          }

set-variable.value:
@{
          var response = ((IResponse)context.Variables["decisionResponse"]).Body.As<JObject>();
          var answers = response["answers"] as JObject;
          if (answers == null) { return "invalid"; }
          var answer = answers["has_pii"] as JObject;
          if (answer == null) { return "invalid"; }
          if ((string)answer["type"] != "choice") { return "invalid"; }
          var choice = answer["choice"];
          if (choice == null || choice.Type != JTokenType.String) { return "invalid"; }
          return (string)choice;
        }
